export enum State {
  LISTENING_BUZZIN_WORD = 0,
  LISTENING_ANSWER_AND_BUZZOUT = 1,
  PROCESSING_AUDIO = 2,
  PROCESSING_ANSWER = 3,
  LISTENING_SUBMIT = 4
}

class StateManager {
  state: State
  update: () => void
  constructor(updater: () => void) {
    this.state = State.LISTENING_BUZZIN_WORD
    this.update = updater
  }
  updateStage() {
    console.log(`[ASR] : Switching from ${this.state} to ${this.state + 1}`)

    this.state++
    this.update()
  }
  resetStage() {
    this.state = State.LISTENING_BUZZIN_WORD
  }
  isListeningForStop() {
    return this.state === State.LISTENING_ANSWER_AND_BUZZOUT
  }
  isListeningForBuzzin() {
    return this.state === State.LISTENING_BUZZIN_WORD
  }
  isListeningForSubmit() {
    return this.state === State.LISTENING_SUBMIT
  }
  isProcessingAudio() {
    return this.state === State.PROCESSING_AUDIO
  }
}

export default StateManager
