import * as React from 'react'
import { useEffect } from 'react'
import SpeechRecognition, {
  SpeechRecognitionOptions,
  useSpeechRecognition
} from 'react-speech-recognition'
import useSound from 'use-sound'
import { useReactMediaRecorder } from 'react-media-recorder'
import useCountDown from 'react-countdown-hook'
import ASREngine, { COMMAND } from './utils/inference'
import useVoiceActivityDetection from './vad'
import StateManager from './manager'

export interface opts {
  audio: {
    buzzin: string
    buzzout: string
  }
  timeout: number
  onAudioData: (data: Array<number>, ...params: Array<any>) => void
  onBuzzin: (...params: Array<any>) => void
  onComplete: (answer: string, audioBlob: Blob, ...params: Array<any>) => void
  onSubmit: (...params: Array<any>) => void
  totalGameTime: number
  ASRthreshold?: number
}

const useOnlineAnswering = (options: opts) => {
  const [answer, setAnswer] = React.useState<Array<string>>([])
  const [audioBlob, setAudioBlob] = React.useState<Blob>()
  const [processingAudio, setProcessingAudio] = React.useState<boolean>(true)
  const updateState = () => {
    console.log('[ASR] State changed to ', ready, '! Updating Commands')
    commandRecognizer.update(commands)
    commandRecognizer.restart()
    console.log('[ASR] Updated Commands')
  }
  const [manager] = React.useState<StateManager>(new StateManager(updateState))
  const [playBuzzin] = useSound(options.audio.buzzin)
  const [playBuzzout] = useSound(options.audio.buzzout)
  const [ready, setReady] = React.useState<boolean>(false)
  const [micPermission, setMicPermission] = React.useState<
    'granted' | 'denied' | 'prompt' | 'unknown'
  >('unknown')
  const [timeLeft, { start, reset, pause }] = useCountDown(options.timeout, 100)
  const [startVoiceActivityDetection, voiceState, volume, error, errormsg] =
    useVoiceActivityDetection(options.totalGameTime)

  const extraCommands: SpeechRecognitionOptions['commands'] = [
    {
      command: 'Stop',
      callback: (_) => {
        console.log('[ASR] : Heard Stopped')

        if (manager.isListeningForStop()) {
          pause()
          setProcessingAudio(true)
          manager.updateStage()
          console.log('[ASR] : Stopped')
          stopRecording()
          commandRecognizer._buzzedin = false
        }
      },
      isFuzzyMatch: true,
      fuzzyMatchingThreshold: 0.2
    },
    {
      command: 'Submit',
      callback: (_) => {
        console.log('[ASR] : Heard Submit!')
        if (manager.isListeningForSubmit()) {
          console.log('[ASR] : Submitting')

          manager.resetStage()
          options.onSubmit()
          recognizer.resetTranscript()
          setAnswer([])
        }
      },
      isFuzzyMatch: true,
      fuzzyMatchingThreshold: 0.2
    }
  ]

  const resetForNewQuestion = () => {
    console.log('[ASR] Resetting for New Question!')
    manager.resetStage()
    recognizer.resetTranscript()
    setProcessingAudio(false)
    setAnswer([])
  }

  const recognizer = useSpeechRecognition({ commands: extraCommands })

  SpeechRecognition.startListening({ continuous: true })

  try {
    ;(navigator as any).permissions
      .query({ name: 'microphone' })
      .then(function (permissionStatus: any) {
        setMicPermission(permissionStatus.state)
      })
  } catch (error) {
    console.log('error')
  }

  const { status, startRecording, stopRecording } = useReactMediaRecorder({
    audio: true,
    onStop: (_: string, blob: Blob) => {
      console.log('[ASR] Stopped Voice Recorder!')
      setAudioBlob(blob)
    }
  })

  const complete = () => {
    console.log('[ASR] : Started Processing Answer into Text Box')
    const transcript =
      recognizer.finalTranscript.length > 0
        ? recognizer.finalTranscript
        : recognizer.interimTranscript
    console.log(
      '[ASR] Final Transcaript :',
      recognizer.finalTranscript,
      'Intermediate Transcript',
      recognizer.interimTranscript,
      'Answer:',
      transcript
    )
    if (transcript.length >= 0 && audioBlob) {
      try {
        playBuzzout()
        options.onComplete(
          transcript
            .split(' ')
            .slice(transcript.toLowerCase().split(' ').indexOf('go'), -1)
            .join(' ')
            .toLowerCase()
            .replace('go'.toLowerCase(), '')
            .replace('stop'.toLowerCase(), '')
            .replace(/[^\w\s]|_/g, ''),
          audioBlob
        )
      } catch (error) {
        console.error(error)
      }
      console.log('[ASR] Processed Answer into Answer Box')
      manager.updateStage() // 3->4
    }
  }

  const commands = [
    {
      command: COMMAND.BUZZIN_COMMAND,
      callback: () => {
        console.log(`[ASR] : Ready: ${ready}`)
        console.log('[ASR] : Heard Go!')
        if (ready && manager.isListeningForBuzzin()) {
          manager.updateStage()
          reset()
          start()
          console.log('[ASR] Buzzed In')
          options.onBuzzin()
          playBuzzin()
          startRecording()
        }
      }
    }
    // {
    //   command: COMMAND.BUZZOUT_COMMAND,
    //   callback: () => {
    //     if (ready && manager.isListeningForStop()) {
    //       console.log('[ASR] : Stopped')
    //       manager.updateStage()
    //       stopRecording()
    //     }
    //   }
    // }
  ]
  const commandRecognizer = new ASREngine(commands, options.ASRthreshold)

  useEffect(() => {
    if (timeLeft === 100) {
      console.log('[ASR] Low Time Left!')
      if (manager.isListeningForStop()) {
        setProcessingAudio(true)
        manager.updateStage()
        console.log('[ASR] : Stopped due to time limit!')
        stopRecording()
        commandRecognizer._buzzedin = false
      }
    }
  }, [timeLeft])

  useEffect(() => {
    if (status == 'stopped') {
      manager.updateStage()
      console.log('[ASR] Blob Ready')
      setProcessingAudio(false)
      complete()
    }
  }, [audioBlob])

  const permissions = {
    ASR: SpeechRecognition.browserSupportsSpeechRecognition(),
    Mic: micPermission
  }

  const initialize = async () => {
    await commandRecognizer.intialize()
  }

  const startListening = () => {
    commandRecognizer.listen()
    startVoiceActivityDetection()
  }

  const stopListening = () => {
    commandRecognizer.stop()
  }

  const setIsReady = (state: boolean) => {
    console.log(state)
    setReady(state)
  }

  useEffect(() => {
    manager.resetStage()
    console.log('[ASR] State changed to ', ready, '! Updating Commands')
    commandRecognizer.update(commands)
    commandRecognizer.restart()
    console.log('[ASR] Updated Commands')
  }, [ready])

  const data = {
    initialize,
    startListening,
    stopListening,
    processingAudio,
    manager,
    recordingState: status,
    timeLeft,
    voiceState,
    volume,
    answer,
    permissions,
    error,
    errormsg,
    ready,
    setIsReady,
    resetForNewQuestion
  }

  return data
}

export default useOnlineAnswering
